window.AnaquelMonitor={start(){build();if(!stat)fetch('./historico.json').then(x=>x.json()).then(j=>{stat=j;tick();}).catch(()=>{});tick();clearInterval(timer);timer=setInterval(tick,1500);},stop(){clearInterval(timer);timer=null;}};
